static Map<String, Integer> countWords(List<String> words) {
    Map<String, Integer> counts = new HashMap<>();
    for (String word : words) {
        String key = word.toLowerCase(Locale.ROOT);
        counts.put(key, counts.get(key) + 1);
    }
    return counts;
}

