solution:
static Map<String, Integer> countWords(List<String> words) {
    Map<String, Integer> counts = new HashMap<>();
    for (String word : words) {
        counts.merge(word.toLowerCase(Locale.ROOT), 1, Integer::sum);
    }
    return counts;
}
